package com.jiugeng.erp.product;
import static com.jiugeng.erp.product.ProductTypes.*;import com.jiugeng.erp.catalogmedia.CatalogImageGateway;import com.jiugeng.erp.iam.*;import com.jiugeng.erp.materialinventory.ProductMaterialAssignmentGateway;import com.jiugeng.erp.supplier.SupplierAssignmentGateway;import java.math.BigDecimal;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class ProductService{private final ProductRepository repo;private final SupplierAssignmentGateway suppliers;private final ProductMaterialAssignmentGateway materials;private final CatalogImageGateway images;private final AuditTrail audit;
ProductService(ProductRepository repo,SupplierAssignmentGateway suppliers,ProductMaterialAssignmentGateway materials,CatalogImageGateway images,AuditTrail audit){this.repo=repo;this.suppliers=suppliers;this.materials=materials;this.images=images;this.audit=audit;}
@Transactional(readOnly=true)List<ProductView> products(boolean supplierAccess){return repo.findAll(supplierAccess);}
@Transactional(readOnly=true)ProductView product(String id,boolean supplierAccess){return repo.findById(id,supplierAccess).orElseThrow(()->missing(id));}
@Transactional ProductView create(ProductInput input,AuthenticatedActor actor,boolean supplierAccess){ValidatedProduct v=validate(input,null);String id=UUID.randomUUID().toString();try{repo.insertProduct(id,v.code,v.normalizedCode,v.name,v.type,v.description,v.status,actor.userId());saveVariants(id,v.variants,false,actor);ProductView created=product(id,supplierAccess);record(actor,"PRODUCT_CREATE",id,null,snapshot(created));return created;}catch(DataIntegrityViolationException e){throw conflict(e);}catch(ProductMaterialAssignmentGateway.AssignmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}catch(SupplierAssignmentGateway.AssignmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}catch(CatalogImageGateway.AttachmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}}
@Transactional ProductView update(String id,ProductInput input,AuthenticatedActor actor,boolean supplierAccess){ProductView before=product(id,true);if(input.version()==null||input.version()!=before.version())throw version();if(input.productCode()==null||!ProductRepository.normalize(before.productCode()).equals(ProductRepository.normalize(input.productCode())))throw new ProductException(409,"PRODUCT_CODE_IMMUTABLE","产品编码保存后不可修改");ValidatedProduct v=validate(input,id);try{if(repo.updateProduct(id,v.name,v.type,v.description,v.status,input.version(),actor.userId())!=1)throw version();saveVariants(id,v.variants,true,actor);ProductView after=product(id,supplierAccess);record(actor,"PRODUCT_UPDATE",id,snapshot(before),snapshot(after));return after;}catch(DataIntegrityViolationException e){throw conflict(e);}catch(ProductMaterialAssignmentGateway.AssignmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}catch(SupplierAssignmentGateway.AssignmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}catch(CatalogImageGateway.AttachmentException e){throw new ProductException(e.status(),e.code(),e.getMessage());}}
@Transactional ProductView disable(String id,long version,AuthenticatedActor actor,boolean supplierAccess){ProductView before=product(id,true);if(before.status()==ProductStatus.DISABLED)return product(id,supplierAccess);if(repo.disableProduct(id,version,actor.userId())!=1)throw version();ProductView after=product(id,supplierAccess);record(actor,"PRODUCT_DISABLE",id,snapshot(before),snapshot(after));return after;}
private ValidatedProduct validate(ProductInput input,String productId){if(input==null)throw invalid("产品请求不能为空");String code=required(input.productCode(),"产品编码",64),normalized=ProductRepository.normalize(code);if(repo.productCodeExists(normalized,productId))throw new ProductException(409,"PRODUCT_CODE_EXISTS","产品编码已存在（忽略大小写）");String name=required(input.productName(),"产品名称",200);List<VariantInput> source=input.variants()==null?List.of():input.variants();if(source.isEmpty()||source.size()>100)throw invalid("产品必须包含 1 至 100 个 SKU");Set<String> codes=new HashSet<>();List<ValidatedVariant> variants=new ArrayList<>();for(VariantInput value:source){ValidatedVariant valid=variant(value,productId);if(!codes.add(valid.normalizedSku))throw new ProductException(409,"SKU_CODE_EXISTS","SKU 编码重复（忽略大小写）");variants.add(valid);}return new ValidatedProduct(code,normalized,name,optional(input.productType(),100),optional(input.description(),1000),input.status()==null?ProductStatus.DRAFT:input.status(),variants);}
private ValidatedVariant variant(VariantInput input,String productId){String id=optional(input.id(),36);if(id!=null&&(productId==null||!repo.variantBelongsToProduct(id,productId)))throw invalid("SKU 不属于当前产品");String sku=required(input.skuCode(),"SKU 编码",64),normalized=ProductRepository.normalize(sku);if(repo.skuCodeExists(normalized,id))throw new ProductException(409,"SKU_CODE_EXISTS","SKU 编码已存在（忽略大小写）");BigDecimal grams=input.packageWeightGrams();if(grams!=null&&(grams.signum()<=0||grams.scale()>3||grams.compareTo(new BigDecimal("999999999.999"))>0))throw invalid("包装重量必须为不超过三位小数的正克数");List<SupplierAssignment> supplierValues=input.suppliers()==null?List.of():List.copyOf(input.suppliers());List<MaterialAssignment> materialValues=input.materials()==null?List.of():List.copyOf(input.materials());return new ValidatedVariant(id,sku,normalized,required(input.variantName(),"SKU 名称",200),optional(input.itemDimensions(),200),optional(input.packageDimensions(),200),grams,input.status()==null?VariantStatus.DRAFT:input.status(),optional(input.imageAssetId(),36),input.version(),supplierValues,materialValues);}
private void saveVariants(String productId,List<ValidatedVariant> values,boolean updating,AuthenticatedActor actor){List<String> existing=updating?repo.findVariantIds(productId):List.of();Set<String> retained=new HashSet<>();for(ValidatedVariant value:values){String id=value.id==null?UUID.randomUUID().toString():value.id;String oldImage=null;if(value.id==null)repo.insertVariant(id,productId,value.sku,value.normalizedSku,value.name,value.itemDimensions,value.packageDimensions,value.grams,value.status,value.imageId,UUID.randomUUID().toString());else{ProductView current=product(productId,true);VariantView prior=current.variants().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow();oldImage=prior.imageAssetId();if(value.version==null||repo.updateVariant(id,value.sku,value.normalizedSku,value.name,value.itemDimensions,value.packageDimensions,value.grams,value.status,value.imageId,value.version)!=1)throw version();}images.attach(value.imageId,CatalogImageGateway.Purpose.SKU_MAIN,"PRODUCT_VARIANT",id,actor);images.releaseReplaced(oldImage,value.imageId,"PRODUCT_VARIANT",id);suppliers.replaceVariantAssignments(id,value.suppliers.stream().map(s->new SupplierAssignmentGateway.Assignment(s.supplierId(),s.purchaseUrl(),s.remark(),s.primary())).toList(),actor);materials.replaceVariantAssignments(productId,id,value.materials.stream().map(m->new ProductMaterialAssignmentGateway.Assignment(m.materialId(),m.standardQuantity(),m.unit(),m.lossRate(),m.remark(),m.enabled())).toList(),actor);retained.add(id);}if(updating)existing.stream().filter(id->!retained.contains(id)).forEach(repo::disableVariant);}
private String required(String v,String label,int max){String r=optional(v,max);if(r==null)throw invalid(label+"不能为空");return r;}private String optional(String v,int max){if(v==null)return null;String r=v.trim();if(r.isEmpty())return null;if(r.length()>max)throw invalid("字段长度超过 "+max);return r;}
private ProductException invalid(String m){return new ProductException(400,"PRODUCT_FIELD_INVALID",m);}private ProductException missing(String id){return new ProductException(404,"PRODUCT_NOT_FOUND","产品不存在："+id);}private ProductException version(){return new ProductException(409,"PRODUCT_VERSION_CONFLICT","产品或 SKU 已被其他用户更新");}private ProductException conflict(Exception e){return new ProductException(409,"PRODUCT_CONFLICT","产品编码、SKU 或关联关系与现有数据冲突");}
private void record(AuthenticatedActor a,String action,String id,Map<String,?>before,Map<String,?>after){audit.record(new AuditTrail.BusinessOperation(a.userId(),a.loginName(),a.displayName(),action,"PRODUCT",id,true,before,after,"产品、SKU、供应商与辅料聚合保存"));}
private Map<String,Object> snapshot(ProductView p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.id());m.put("productCode",p.productCode());m.put("productName",p.productName());m.put("status",p.status());m.put("version",p.version());m.put("skuCodes",p.variants().stream().map(VariantView::skuCode).toList());m.put("supplierIds",p.variants().stream().flatMap(v->v.suppliers().stream()).map(SupplierAssignment::supplierId).distinct().toList());return m;}
private record ValidatedProduct(String code,String normalizedCode,String name,String type,String description,ProductStatus status,List<ValidatedVariant> variants){}
private record ValidatedVariant(String id,String sku,String normalizedSku,String name,String itemDimensions,String packageDimensions,BigDecimal grams,VariantStatus status,String imageId,Long version,List<SupplierAssignment> suppliers,List<MaterialAssignment> materials){}
}
